 @BeforeAll static void provider(){Assumptions.assumeTrue(System.getenv("NIGSON_TEST_JDBC_URL")!=null,"native owner DB required");Path root=Path.of(System.getProperty("user.dir")).toAbsolutePath();while(root!=null&&!java.nio.file.Files.isDirectory(root.resolve("tests/mocks/target")))root=root.getParent();if(root==null)throw new IllegalStateException("LOCAL_MOCK_EXTENSION_NOT_FOUND");mock=new GenericContainer<>(DockerImageName.parse("wiremock/wiremock:3.13.2@sha256:0d4ecb3e4dc8213fd7a4d37d6a78f6e6b553a6d2e15bd51b0999781282ac61b3")).withEnv("MOCK_PROVIDER","twilio").withEnv("APP_ENV","test").withCopyFileToContainer(MountableFile.forHostPath(root.resolve("tests/mocks/target/provider-state.jar")),"/var/wiremock/extensions/provider-state.jar").withCommand("--extensions","com.nigson.mocks.ProviderStateExtension","--no-request-journal","--disable-request-logging").withExposedPorts(8080).withCreateContainerCmdModifier(cmd->cmd.getHostConfig().withPortBindings(new PortBinding(Ports.Binding.bindIpAndPort("127.0.0.1",0),new ExposedPort(8080))));mock.start();endpoint="http://127.0.0.1:"+mock.getMappedPort(8080);}
