 @BeforeEach void setup()throws Exception{f=new VerificationIntakePersistenceTest();f.setup();admin("reset",Map.of());time=new AtomicReference<>(Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS));clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return time.get();}};suppression=new AtomicReference<>(false);suppressionStatus=new AtomicReference<>(200);suppressionReads=new AtomicInteger();experience=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);experience.setExecutor(Executors.newVirtualThreadPerTaskExecutor());experience.createContext("/internal/v1/leads/",x->{assertThat(x.getRequestMethod()).isEqualTo("GET");assertThat(x.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer test-workload");assertThat(x.getRequestHeaders().getFirst("X-Nigson-Actor")).isNotBlank();assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();byte[] json=EventCodec.JSON.writeValueAsBytes(Map.of("phone",phone,"channel","WHATSAPP","destinationHash",destinationHash,"eligible",true,"basis","SIGNED_INBOUND_REQUEST","approvedTemplateCodes",List.of("STAFF_LEAD_REPLY")));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,json.length);x.getResponseBody().write(json);x.close();});experience.createContext("/internal/v1/notification-suppression-checks",x->{suppressionReads.incrementAndGet();assertThat(x.getRequestMethod()).isEqualTo("POST");assertThat(x.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer test-workload");assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();var req=EventCodec.JSON.readTree(x.getRequestBody().readAllBytes());assertThat(req.path("destinationHash").asString()).isEqualTo(destinationHash);int status=suppressionStatus.get();byte[] json=EventCodec.JSON.writeValueAsBytes(Map.of("suppressed",suppression.get()));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(status,json.length);x.getResponseBody().write(json);x.close();});experience.start();source=new StaffReplySource("test","http://127.0.0.1:"+experience.getAddress().getPort(),route->{assertThat(Set.of("API-194","API-205")).contains(route.api());return "test-workload";},clock);crypto=new StaffReplyCrypto("staff-test-r1",fill(32,(byte)7),fill(32,(byte)11));provider=new TwilioAdapter("test",ProviderHttp.Mode.MOCK,endpoint,f.account,"mock-twilio-token","MG"+"0".repeat(32));execution=new StaffReplyExecution(f.jdbc,f.manager,f.audit,clock,ProviderHttp.Mode.MOCK,provider.accountFingerprint(),f.generation,time.get().minusSeconds(60),new SimpleMeterRegistry());worker=new StaffReplyWorker(execution,source,new StaffReplyMessage("test","http://127.0.0.1:9/api/v1/webhooks/notifications/twilio/status",crypto),crypto,provider,clock);var gen=KeyPairGenerator.getInstance("EC");gen.initialize(new ECGenParameterSpec("secp256r1"));keys=gen.generateKeyPair();lead=UUID.randomUUID();correlation=UUID.randomUUID();command=UUID.randomUUID();template=UUID.randomUUID();var schema=EventCodec.JSON.readTree("{\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"message\":{\"type\":\"string\",\"maxLength\":120}},\"required\":[\"message\"]}");f.jdbc.update("INSERT INTO integration.notification_template(id,created_by,updated_by,code,revision,locale,channel,body,classification,active,provider_template_id,variables_schema) VALUES (?,'test','test','STAFF_LEAD_REPLY',?,'en-NG','WHATSAPP','Approved staff lead reply','TRANSACTIONAL',true,?,?::jsonb)",template,f.revision,contentSid,EventCodec.JSON.writeValueAsString(schema));assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.notification_template WHERE id=? AND code='STAFF_LEAD_REPLY' AND channel='WHATSAPP' AND locale='en-NG' AND provider_template_id=? AND active",Integer.class,template,contentSid)).isEqualTo(1);String issuer="http://identity.synthetic.invalid/realms/test";commands=new LeadReplyCommandService(f.jdbc,f.audit,new SimpleMeterRegistry(),f.manager,source,crypto,provider,clock,f.generation,"en-NG",f.revision,Map.of("active",(java.security.interfaces.ECPublicKey)keys.getPublic()),Set.of(issuer),Set.of("STAFF_LEAD_REPLY"),contentSid);}
 @AfterEach void stop(){if(f!=null){f.jdbc.update("UPDATE integration.notification_dispatch SET stage='FAILED',lease_until=NULL,next_attempt_at=now()+interval '1 day',updated_at=now(),updated_by='staff-reply-test-cleanup' WHERE id IN (SELECT id FROM integration.notification_job WHERE created_by='api-193' AND template_code='STAFF_LEAD_REPLY')");f.jdbc.update("UPDATE integration.notification_job SET state='FAILED',lease_until=NULL,next_attempt_at=now()+interval '1 day',updated_at=now(),updated_by='staff-reply-test-cleanup' WHERE created_by='api-193' AND template_code='STAFF_LEAD_REPLY'");}if(experience!=null)experience.stop(0);}
 static byte[] fill(int n,byte v){byte[] b=new byte[n];Arrays.fill(b,v);return b;}
 ActorAssertion.Actor actor(){return new ActorAssertion.Actor(UUID.fromString("aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"),"http://identity.synthetic.invalid/realms/test","staff-subject",null,Set.of("SALES"),Set.of("notification.send_WITH_SIGNED_ACTOR","notification.read_WITH_SIGNED_ACTOR"),null);}
 String assertion(String path,String method,String audience,String operation,byte[] body)throws Exception{var binding=new ActorAssertion.Binding(audience,operation,method,path,correlation,ActorAssertion.Binding.bodyHash(body));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID("active").type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(actor(),binding,clock.instant()));jwt.sign(new ECDSASigner((ECPrivateKey)keys.getPrivate()));return jwt.serialize();}
 PrivateWorkload.Proof proof(){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-193")).findFirst().orElseThrow();return new PrivateWorkload.Proof(route.client(),"service-subject",route,actor());}
 LeadReplyValues.Command input(String value){return new LeadReplyValues.Command(command,lead,"STAFF_LEAD_REPLY","WHATSAPP",Map.of("message",value));}
 LeadReplyValues.Response enqueue(String value)throws Exception{return commands.enqueue(proof(),assertion("/internal/v1/leads/"+lead+"/messaging-context","GET","experience","notification.read_WITH_SIGNED_ACTOR",new byte[0]),input(value),correlation);}
 static tools.jackson.databind.JsonNode admin(String op,Map<String,Object> body)throws Exception{var req=HttpRequest.newBuilder(URI.create(endpoint+"/__scenario/"+op)).timeout(Duration.ofSeconds(10));var result=HTTP.send(body==null?req.GET().build():req.header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(EventCodec.JSON.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());assertThat(result.statusCode()).isEqualTo(200);return EventCodec.JSON.readTree(result.body());}
 int operations()throws Exception{return admin("state",null).path("operations").size();}
 @Test void commandPersistsEncryptedStableContextAndWorkerSendsOneMockMessage()throws Exception{var response=enqueue("We have received your request");assertThat(response.state()).isEqualTo("PENDING");assertThat(response.jobId()).isEqualTo(command);var row=f.jdbc.queryForMap("SELECT j.state,j.destination_hash,d.* FROM integration.notification_job j JOIN integration.notification_dispatch d ON d.id=j.id WHERE j.id=?",command);byte[] recipient=(byte[])row.get("recipient_ciphertext"),variables=(byte[])row.get("variables_ciphertext"),clearVariables=EventCodec.JSON.writeValueAsBytes(new TreeMap<>(input("We have received your request").variables()));assertThat(row.get("state")).isEqualTo("PENDING");assertThat(row.get("command_hash")).isEqualTo(crypto.commandHash(LeadReplyValues.canonical(input("We have received your request"))));assertThat(recipient).isNotEqualTo(phone.getBytes(java.nio.charset.StandardCharsets.UTF_8));assertThat(variables).isNotEqualTo(clearVariables);assertThat(crypto.decrypt(command,"RECIPIENT",recipient)).isEqualTo(phone.getBytes(java.nio.charset.StandardCharsets.UTF_8));assertThat(crypto.decrypt(command,"VARIABLES",variables)).isEqualTo(clearVariables);assertThat(row.get("context_basis")).isEqualTo("SIGNED_INBOUND_REQUEST");assertThat(operations()).isZero();assertThat(enqueue("We have received your request")).isEqualTo(response);assertThatThrownBy(()->commands.enqueue(proof(),assertion("/internal/v1/leads/"+lead+"/messaging-context","GET","experience","notification.read_WITH_SIGNED_ACTOR",new byte[0]),input("Changed content"),correlation)).isInstanceOfSatisfying(Problem.Failure.class,e->assertThat(e.code).isEqualTo(ProblemCode.IDEMPOTENCY_HASH_MISMATCH));assertThat(worker.process(execution.claim().orElseThrow())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT state FROM integration.notification_job WHERE id=?",String.class,command)).isEqualTo("SENT");assertThat(f.jdbc.queryForObject("SELECT stage FROM integration.notification_dispatch WHERE id=?",String.class,command)).isEqualTo("ACCEPTED");assertThat(operations()).isEqualTo(1);assertThat(suppressionReads).hasValue(1);}
 @Test void latestSuppressionAndSuppressionOutageNeverCallProvider()throws Exception{enqueue("Safe reply");suppression.set(true);worker.process(execution.claim().orElseThrow());assertThat(f.jdbc.queryForObject("SELECT state FROM integration.notification_job WHERE id=?",String.class,command)).isEqualTo("SUPPRESSED");assertThat(operations()).isZero();}
 @Test void suppressionServiceFailureAfterCheckpointBecomesUnknownWithoutSend()throws Exception{enqueue("Safe reply");suppressionStatus.set(503);worker.process(execution.claim().orElseThrow());assertThat(f.jdbc.queryForObject("SELECT state FROM integration.notification_job WHERE id=?",String.class,command)).isEqualTo("UNKNOWN");assertThat(f.jdbc.queryForObject("SELECT stage FROM integration.notification_dispatch WHERE id=?",String.class,command)).isEqualTo("UNKNOWN");assertThat(operations()).isZero();}
