 @Test void invalidSecondAssertionAndInactiveTemplateNeverCommit()throws Exception{String wrong=assertion("/internal/v1/leads/"+UUID.randomUUID()+"/messaging-context","GET","experience","notification.read_WITH_SIGNED_ACTOR",new byte[0]);assertThatThrownBy(()->commands.enqueue(proof(),wrong,input("Safe reply"),correlation)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);f.jdbc.update("UPDATE integration.notification_template SET active=false WHERE id=?",template);assertThatThrownBy(()->enqueue("Safe reply")).isInstanceOf(Problem.Failure.class);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.notification_job WHERE id=?",Integer.class,command)).isZero();}
 @Test void sentStaffReplyAcceptsSignedReceiptAndProjectsDeliveredMonotonically()throws Exception{enqueue("Safe reply");worker.process(execution.claim().orElseThrow());String sid=f.jdbc.queryForObject("SELECT provider_message_id FROM integration.notification_dispatch WHERE id=?",String.class,command);var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-189")&&r.client().equals("nigson-commerce")).findFirst().orElseThrow();var receiptService=new NotificationReceiptService(f.jdbc,f.manager,f.audit,clock,new SimpleMeterRegistry());var receiptProof=new PrivateWorkload.Proof("nigson-commerce","test-commerce",route,null);var receipt=new NotificationReceiptValues(command,"TWILIO",provider.accountSid(),sid,"delivered","d".repeat(64),null,time.get());assertThat(receiptService.receive(receiptProof,receipt,correlation)).isTrue();assertThat(f.jdbc.queryForObject("SELECT state FROM integration.notification_job WHERE id=?",String.class,command)).isEqualTo("DELIVERED");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.message_receipt WHERE job_id=?",Integer.class,command)).isEqualTo(1);var stale=new NotificationReceiptValues(command,"TWILIO",provider.accountSid(),sid,"sent","e".repeat(64),null,time.get());assertThat(receiptService.receive(receiptProof,stale,correlation)).isTrue();assertThat(f.jdbc.queryForObject("SELECT state FROM integration.notification_job WHERE id=?",String.class,command)).isEqualTo("DELIVERED");}
 @Test void concurrentConflictingCommandsCommitOnlyOneFrozenIntent()throws Exception{var start=new CountDownLatch(1);var ready=new CountDownLatch(2);try(var pool=Executors.newFixedThreadPool(2)){var tasks=List.of("First reply","Second reply").stream().<Callable<Object>>map(value->()->{ready.countDown();start.await();try{return enqueue(value);}catch(Throwable failure){return failure;}}).toList();var a=pool.submit(tasks.get(0));var b=pool.submit(tasks.get(1));assertThat(ready.await(5,TimeUnit.SECONDS)).isTrue();start.countDown();var results=List.of(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertThat(results.stream().filter(LeadReplyValues.Response.class::isInstance)).hasSize(1);assertThat(results.stream().filter(Problem.Failure.class::isInstance).map(Problem.Failure.class::cast).map(failure->failure.code)).containsExactly(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.notification_job WHERE id=?",Integer.class,command)).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.notification_dispatch WHERE id=?",Integer.class,command)).isEqualTo(1);assertThat(operations()).isZero();}}
